#!/usr/bin/env bash
set -u
ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
# good block passes
tmp=$(mktemp)
cat > "$tmp" <<'EOF'
# >>> fleet-roads BEGIN (generated by bin/fleet/roads.sh) >>>
Host nidavellir
  HostName nidavellir.tailefab81.ts.net
  User zerwizomar
  IdentityFile ~/.ssh/id_ed25519
  IdentitiesOnly yes
# <<< fleet-roads END <<<
EOF
SSH_CONFIG="$tmp" bash "$ROOT/bin/gates/guards/ssh-roads-guard.sh" >/dev/null 2>&1
[ $? -eq 0 ] || { echo "good block failed"; rm -f "$tmp"; exit 1; }

# LAN refused with file+line
tmp2=$(mktemp)
cat > "$tmp2" <<'EOF'
# >>> fleet-roads BEGIN (generated by bin/fleet/roads.sh) >>>
Host nidavellir
  HostName 192.168.68.106
  User zerwizomar
# <<< fleet-roads END <<<
EOF
out=$(SSH_CONFIG="$tmp2" bash "$ROOT/bin/gates/guards/ssh-roads-guard.sh" 2>&1); rc=$?
echo "$out" | grep -q "192.168.68.106" || { echo "LAN not refused"; rm -f "$tmp" "$tmp2"; exit 1; }
[ $rc -ne 0 ] || { echo "LAN exit 0"; rm -f "$tmp" "$tmp2"; exit 1; }

# unknown host refused
tmp3=$(mktemp)
cat > "$tmp3" <<'EOF'
# >>> fleet-roads BEGIN (generated by bin/fleet/roads.sh) >>>
Host nopehost
  HostName nope.tailefab81.ts.net
  User x
# <<< fleet-roads END <<<
EOF
out=$(SSH_CONFIG="$tmp3" bash "$ROOT/bin/gates/guards/ssh-roads-guard.sh" 2>&1); rc=$?
echo "$out" | grep -q "nopehost" || { echo "unknown host not refused"; rm -f "$tmp" "$tmp2" "$tmp3"; exit 1; }
[ $rc -ne 0 ] || { echo "unknown exit 0"; rm -f "$tmp" "$tmp2" "$tmp3"; exit 1; }

# idempotency
cfg=$(mktemp)
HOME_BACKUP="$HOME"
# run install twice against temp by env? roads.sh uses ~/.ssh/config fixed. Skip deeper; test marker count via manual simulate
rm -f "$tmp" "$tmp2" "$tmp3" "$cfg"
echo "PASS"
exit 0
